  /**
   * Record scheduler progress (write-then-emit).
   */
  recordSchedulerProgress(progress: {
    iterationsStarted?: number;
    skippedIds?: IssueId[];
  }): void {
    this.assertActive();
    this.tracker.update((state) => ({
      ...state,
      scheduler: {
        ...state.scheduler,
        iterationsStarted:
          progress.iterationsStarted ?? state.scheduler.iterationsStarted,
        skippedIds: progress.skippedIds ?? state.scheduler.skippedIds,
      },
    }));
    this.emit({
      kind: "schedulerProgressed",
      iterationsStarted: progress.iterationsStarted,
      skippedIds: progress.skippedIds,
    });
  }

  /**
   * Record a whole-run review phase change (write-then-emit). No-op if the
   * tracker is missing — matches the pre-existing `recordReviewPhaseSafely`
   * semantics so callers can invoke this during shutdown races.
   */
  recordWholeRunReviewPhase(phase: ReviewPhase): void {
    this.assertActive();
    if (!this.tracker.read()) return;
    this.tracker.recordReviewPhase(phase);
    this.emit({ kind: "wholeRunReviewPhaseChanged", phase });
  }

  /**
   * Record an Agent Client Execution's usage (write-then-emit).
   *
   * Allocates the next run-scoped monotonic `executionId`, appends one
   * usage ledger entry, recomputes the summary from the full ledger,
   * and writes via `tracker.update()`. Missing usage produces a
   * ledger entry whose token/cost fields are `null`. Error strings are
   * truncated to at most 500 characters.
   *
   * This method must not throw after an Agent Client Execution returns.
   * Persistence failures are caught and warned to the console.
   */
  recordUsage(input: {
    phase: PromptPhase;
    issueId?: IssueId;
    attempt?: number;
    client: PromptClientKind;
    model?: string;
    success: boolean;
    error?: string;
    usage?: AgentExecutionUsage;
  }): void {
    this.assertActive();
    try {
      let entry: UsageLedgerEntry | undefined;
      this.tracker.update((state) => {
        const executionId = state.usageLedger.length + 1;
        entry = {
          executionId,
          phase: input.phase,
          issueId: input.issueId,
          attempt: input.attempt,
          client: input.client,
          model: input.model,
          outcome: input.success ? "succeeded" : "failed",
          error: input.error != null
            ? input.error.slice(0, 500)
            : undefined,
          inputTokens: input.usage?.inputTokens ?? null,
          outputTokens: input.usage?.outputTokens ?? null,
          cacheReadTokens: input.usage?.cacheReadTokens ?? null,
          cacheWriteTokens: input.usage?.cacheWriteTokens ?? null,
          reasoningTokens: input.usage?.reasoningTokens ?? null,
          totalTokens: input.usage?.totalTokens ?? null,
          costUsd: input.usage?.costUsd ?? null,
          perModelUsage: input.usage?.perModelUsage,
        };
        const usageLedger = [...state.usageLedger, entry!];
        return {
          ...state,
          usageLedger,
          usageSummary: buildUsageSummary(usageLedger),
        };
      });
      this.emit({ kind: "usageRecorded", entry: entry! });
    } catch (err) {
      console.warn(`Usage recording failed: ${(err as Error).message}`);
    }
  }

